Approach - By Using in-built library functions - O(n) Time and O(1) SpaceWe can also use inbuilt library functions to search for a character in a string. This makes the search simple and easier to implement. 
            C++

    #include <iostream>
#include <string>

using namespace std;

int findCharacterIndex(const string& s, char ch) {
    size_t idx = s.find(ch);

    if (idx != string::npos) {
        return idx;
    } else {
        return -1;
    }
}

int main() {
    string s = "geeksforgeeks";
    char ch = 'k';

    int index = findCharacterIndex(s, ch);
    cout << index << endl;

    return 0;
}


            C

    #include <stdio.h>
#include <string.h>

int findCharacterIndex(const char* s, char ch) {
    char* ptr = strchr(s, ch);
    if (ptr != NULL) {
        return ptr - s;
    } else {
        return -1;
    }
}

int main() {
    const char* s = "geeksforgeeks";
    char ch = 'k';

    int index = findCharacterIndex(s, ch);
    printf("%d\n", index);

    return 0;
}


